class SyncSummary:
    """Resolve the frozen tip descriptor (height/length/status) for a synced
    candidate during recovery, from either a surviving fork or a canonical
    chain prefix.
    """

    @staticmethod
    def from_blocks_raw(tip_hash: str, blocks_raw: list[dict]) -> dict | None:
        """Build the descriptor for an already-resolved raw block list whose
        last block hash must equal ``tip_hash``.
        """
        if not blocks_raw:
            return None
        tip = blocks_raw[-1]
        if tip.get("block_hash") != tip_hash:
            return None
        return {
            "height": tip["height"],
            "length": len(blocks_raw),
            "status": tip["status"],
        }

    @classmethod
    def from_locations(
        cls,
        tip_hash: str,
        forks: dict[str, list[Block]],
        canonical_chain: list[Block],
    ) -> dict | None:
        """Resolve a descriptor among surviving forks first, then canonical
        blocks (the delivered fork may since have been adopted).
        """
        fork = forks.get(tip_hash)
        if fork is not None:
            return cls.from_blocks_raw(tip_hash, [block.to_dict() for block in fork])
        prefix: list[dict] = []
        for block in canonical_chain:
            prefix.append(block.to_dict())
            if block.block_hash == tip_hash:
                return cls.from_blocks_raw(tip_hash, prefix)
        return None


class StateRecoveryError(ValueError):
    """Raised when no usable on-disk state can be recovered on startup.

    Carries the candidate ``path`` that failed and a human-readable ``reason``
    so callers can report (or catch) the failure explicitly. The exception is a
    ``ValueError`` subclass, so older callers expecting ``ValueError`` on a
    corrupt state file keep working.
    """

    def __init__(self, path: str, reason: str) -> None:
        self.path = path
        self.reason = reason
        super().__init__(f"cannot recover ledger state from {path}: {reason}")

    def test_malformed_bundles(self) -> None:
        for bad in (None, [], "x", 42, {}, {"source": "node-a"}):
            self.assertEqual(
                verify_bundle(bad, self.trust, now=NOW),
                {"ok": False, "error": ERR_INPUT},
            )

    def test_missing_required_fields(self) -> None:
        good = self.bundle()
        for field in ("source", "expires_at", "response", "candidate", "proofs"):
            bad = dict(good)
            del bad[field]
            self.assertEqual(
                verify_bundle(bad, self.trust, now=NOW),
                {"ok": False, "error": ERR_INPUT},
            )

    def test_malformed_trust(self) -> None:
        bad_documents = (
            None,
            {},
            {"genesis_hash": "zz"},
            {"genesis_hash": self.genesis.block_hash, "sources": []},
            {
                "genesis_hash": self.genesis.block_hash,
                "sources": {
                    "node-a": {"public_key": "abc", "expires_at": FUTURE}
                },
            },
            {"genesis_hash": self.genesis.block_hash, "allowlist": []},
            {
                "genesis_hash": self.genesis.block_hash,
                "allowlist": {"node-b": "soon"},
            },
        )
        for bad in bad_documents:
            self.assertEqual(
                verify_bundle(self.bundle(), bad, now=NOW),
                {"ok": False, "error": ERR_INPUT},
            )

    def test_bool_expiry_rejected(self) -> None:
        bundle = self.bundle()
        bundle["expires_at"] = True
        bundle.pop("signature", None)
        self.assertEqual(
            verify_bundle(bundle, self.trust, now=NOW),
            {"ok": False, "error": ERR_INPUT},
        )

    def test_non_dict_response_rejected(self) -> None:
        bundle = self.bundle(response=["not", "an", "object"])
        self.assertEqual(
            verify_bundle(bundle, self.trust, now=NOW),
            {"ok": False, "error": ERR_INPUT},
        )

    def test_empty_candidate_rejected(self) -> None:
        bundle = self.bundle()
        bundle["candidate"] = []
        self.resign(bundle)
        self.assertEqual(
            verify_bundle(bundle, self.trust, now=NOW),
            {"ok": False, "error": ERR_INPUT},
        )

    def test_string_height_in_candidate_rejected(self) -> None:
        bundle = self.bundle()
        bundle["candidate"][1]["height"] = "1"
        self.resign(bundle)
        self.assertEqual(
            verify_bundle(bundle, self.trust, now=NOW),
            {"ok": False, "error": ERR_INTEGRITY},
        )


